SELECT 
FROM SYS_NOTIFICATION_READ


        AND NOTIFICATION_ID = #{queryVO.notificationId}


        AND USER_ID = #{queryVO.userId}


        AND READ_STATUS = #{queryVO.readStatus}




                AND DATE(READ_TIME) >= #{queryVO.startDate}


                AND TRUNC(READ_TIME) >= TO_DATE(#{queryVO.startDate}, 'YYYY-MM-DD')






                AND DATE(read_TIME) <= #{queryVO.endDate}


                AND TRUNC(read_TIME) <= TO_DATE(#{queryVO.endDate}, 'YYYY-MM-DD')




ORDER BY READ_TIME DESC

SELECT 
FROM SYS_NOTIFICATION_READ
WHERE NOTIFICATION_ID = #{notificationId}
AND USER_ID = #{userId}
LIMIT 1

SELECT n.NOTIFICATION_ID as notificationId, n.NOTIFICATION_TITLE as notificationTitle, n.NOTIFICATION_TYPE as notificationType, n.NOTIFICATION_LEVEL as notificationLevel, n.IS_TOP as isTop, n.IS_POPUP as isPopup, n.PUBLISH_TIME as publishTime FROM SYS_NOTIFICATION n LEFT JOIN SYS_NOTIFICATION_READ r ON n.NOTIFICATION_ID = r.NOTIFICATION_ID AND r.USER_ID = #{userId} WHERE n.NOTIFICATION_STATUS = 'PUBLISHED' AND (n.EXPIRE_TIME IS NULL OR n.EXPIRE_TIME > NOW() SYSDATE ) AND ( n.PUBLISH_SCOPE = 'ALL' OR (n.PUBLISH_SCOPE = 'USERS' AND FIND_IN_SET(#{userId}, n.TARGET_USERS)) ) AND (r.READ_STATUS IS NULL OR r.READ_STATUS = 'UNREAD') ORDER BY n.IS_TOP DESC, n.PUBLISH_TIME DESC
LIMIT #{limit}
AND ROWNUM <= #{limit}

SELECT n.NOTIFICATION_ID as notificationId, n.NOTIFICATION_TITLE as notificationTitle, n.NOTIFICATION_TYPE as notificationType, n.NOTIFICATION_LEVEL as notificationLevel, n.PUBLISH_TIME as publishTime, r.READ_TIME as readTime, r.READ_STATUS as readStatus FROM SYS_NOTIFICATION n INNER JOIN SYS_NOTIFICATION_READ r ON n.NOTIFICATION_ID = r.NOTIFICATION_ID WHERE r.USER_ID = #{userId} AND r.READ_STATUS IN ('READ', 'starred', 'archived') ORDER BY r.READ_TIME DESC
LIMIT #{limit}
AND ROWNUM <= #{limit}

